mkdir Architecture && cat > Architecture/LayerDependencyTests.cs <<'EOF'
using System.Reflection;
using System.Reflection.Metadata;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>Build gate: business code may only depend on an allow-list of namespaces.</summary>
public sealed class LayerDependencyTests
{
    // The language core without I/O, network or persistence. Anything not listed is rejected.
    private static readonly string[] LanguageCore =
    [
        "System",
        "System.Collections.Generic",
        "System.Linq",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Runtime.Versioning",
        "System.Diagnostics.CodeAnalysis",
        "System.Reflection", // assembly-level attributes emitted by the compiler
    ];

    [Fact]
    public void Domain_depends_only_on_Domain_and_the_language_core()
    {
        var violations = Violations(typeof(Money).Assembly, ["PaymentAuthorization.Domain"]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    [Fact]
    public void Application_depends_only_on_Application_Domain_and_the_language_core()
    {
        var violations = Violations(
            typeof(AuthorizePayment).Assembly,
            ["PaymentAuthorization.Application", "PaymentAuthorization.Domain"]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    private static List<string> Violations(Assembly assembly, string[] allowedLayers)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new System.Reflection.PortableExecutable.PEReader(stream);
        var reader = pe.GetMetadataReader();
        var found = new List<string>();

        foreach (var handle in reader.TypeReferences)
        {
            var type = reader.GetTypeReference(handle);
            if (type.ResolutionScope.Kind == HandleKind.TypeReference) continue; // nested: checked via its declaring type

            var ns = reader.GetString(type.Namespace);
            var name = reader.GetString(type.Name);
            var allowed = LanguageCore.Contains(ns)
                || allowedLayers.Any(l => ns == l || ns.StartsWith(l + ".", StringComparison.Ordinal));
            if (!allowed) found.Add($"{assembly.GetName().Name} -> {ns}.{name}");
        }

        return found;
    }
}
EOF
cd ../.. && dotnet test tests/PaymentAuthorization.IntegrationTest 2>&1 | tail -15

